const chatId  = $('Telegram Trigger').first().json.message.chat.id.toString();
const filePath = $input.first().json.file_path;
const botToken = 'TU_BOT_TOKEN'; // reemplaza con tu token
const photoUrl = `https://api.telegram.org/file/bot${botToken}/${filePath}`;

// Use workflow static data for session storage per chat
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[chatId]) staticData.sessions[chatId] = { photos: [], texto: '' };

staticData.sessions[chatId].photos.push(photoUrl);
const count = staticData.sessions[chatId].photos.length;

return [{ json: { chatId, photoUrl, count } }];

const chatId = $('Telegram Trigger').first().json.message.chat.id.toString();
const texto  = $('Telegram Trigger').first().json.message.text || '';

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.sessions[chatId]) staticData.sessions[chatId] = { photos: [], texto: '' };

staticData.sessions[chatId].texto += (staticData.sessions[chatId].texto ? '\n' : '') + texto;

return [{ json: { chatId, texto, totalTexto: staticData.sessions[chatId].texto } }];

const chatId = $('Telegram Trigger').first().json.message.chat.id.toString();
const staticData = $getWorkflowStaticData('global');
const session = staticData.sessions?.[chatId] || { photos: [], texto: '' };

if (!session.texto && session.photos.length === 0) {
  return [{ json: { chatId, error: 'empty', photos: [], texto: '' } }];
}

return [{ json: { chatId, photos: session.photos, texto: session.texto, photoCount: session.photos.length } }];

const aiRaw   = $input.first().json.content[0].text || '';
const session = $('Cargar sesión').first().json;

// Parse AI JSON
let prop = {};
try {
  const clean = aiRaw.replace(/```json|```/g, '').trim();
  prop = JSON.parse(clean);
} catch(e) {
  prop = {
    titulo: 'Propiedad en Venta',
    tipo_propiedad: 'Propiedad',
    operacion: 'Venta',
    precio: 'Consultar',
    descripcion_larga: session.texto,
    caracteristicas: []
  };
}

// Build photo HTML (max 6 photos in grid)
const photos = (session.photos || []).slice(0, 6);
const photoHTML = photos.length > 0
  ? photos.map((url, i) =>
      `<img src="${url}" style="width:100%;height:180px;object-fit:cover;border-radius:6px;" />`
    ).join('')
  : '<div style="width:100%;height:180px;background:#e8e8e8;border-radius:6px;display:flex;align-items:center;justify-content:center;color:#999;">Sin fotos</div>';

// Build characteristics HTML
const chars = (prop.caracteristicas || []);
const charHTML = chars.length > 0
  ? chars.map(c => `<li style="margin-bottom:4px;">${c}</li>`).join('')
  : '';

// Build specs grid
const specs = [
  ['Tipo', prop.tipo_propiedad],
  ['Operación', prop.operacion],
  ['m² Construidos', prop.m2_construidos],
  ['m² Terreno', prop.m2_terreno],
  ['Recámaras', prop.recamaras],
  ['Baños Completos', prop.banos_completos],
  ['Medios Baños', prop.medios_banos],
  ['Niveles', prop.niveles],
  ['Estacionamientos', prop.estacionamientos],
  ['Antigüedad', prop.antiguedad],
  ['Mantenimiento', prop.mantenimiento],
  ['Amueblado', prop.amueblado === true ? 'Sí' : prop.amueblado === false ? 'No' : null],
  ['Mascotas', prop.mascotas === true ? 'Permitidas' : prop.mascotas === false ? 'No permitidas' : null],
].filter(([_, v]) => v !== null && v !== undefined && v !== '');

const specsHTML = specs.map(([k, v]) =>
  `<tr><td style="padding:6px 10px;font-weight:600;color:#555;background:#f8f8f8;border:1px solid #e0e0e0;font-size:12px;">${k}</td>
       <td style="padding:6px 10px;color:#222;border:1px solid #e0e0e0;font-size:12px;">${v}</td></tr>`
).join('');

const today = new Date().toLocaleDateString('es-MX', { year:'numeric', month:'long', day:'numeric' });

// Determine grid columns for photos
const gridCols = photos.length === 1 ? '1fr' : photos.length === 2 ? '1fr 1fr' : photos.length >= 3 ? '1fr 1fr 1fr' : '1fr';

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ficha Técnica — ${prop.titulo || 'Propiedad'}</title>
<style>
  * { margin:0; padding:0; box-sizing:border-box; }
  body { font-family: 'Arial', sans-serif; background:#fff; color:#222; }
  .page { width:794px; min-height:1123px; padding:0; }

  /* HEADER */
  .header { background:#1a3a5c; color:#fff; padding:24px 32px; display:flex; justify-content:space-between; align-items:center; }
  .header-logo { font-size:22px; font-weight:700; letter-spacing:1px; }
  .header-logo span { color:#d4af37; }
  .header-tag { background:#d4af37; color:#1a3a5c; padding:6px 16px; border-radius:20px; font-weight:700; font-size:13px; }

  /* HERO PRICE */
  .hero { background:#f0f4f8; padding:20px 32px; border-bottom:3px solid #d4af37; }
  .prop-title { font-size:22px; font-weight:700; color:#1a3a5c; margin-bottom:4px; }
  .prop-address { font-size:13px; color:#666; margin-bottom:12px; }
  .price-tag { font-size:28px; font-weight:700; color:#1a3a5c; }
  .price-m2 { font-size:13px; color:#888; margin-top:2px; }

  /* PHOTOS */
  .photos-section { padding:20px 32px 12px; }
  .photos-grid { display:grid; grid-template-columns:${gridCols}; gap:8px; }
  .section-title { font-size:14px; font-weight:700; color:#1a3a5c; text-transform:uppercase; letter-spacing:1px; border-left:3px solid #d4af37; padding-left:10px; margin-bottom:12px; }

  /* TWO COLUMNS */
  .two-col { display:grid; grid-template-columns:1fr 1fr; gap:20px; padding:16px 32px; }
  .col-section { }

  /* SPECS TABLE */
  table { width:100%; border-collapse:collapse; }

  /* DESCRIPTION */
  .desc-section { padding:0 32px 16px; }
  .desc-text { font-size:13px; line-height:1.7; color:#444; }

  /* CARACTERÍSTICAS */
  ul { padding-left:18px; }
  li { font-size:12px; color:#444; }

  /* FOOTER */
  .footer { background:#1a3a5c; color:#aab8c8; padding:16px 32px; font-size:11px; display:flex; justify-content:space-between; align-items:center; margin-top:auto; }
  .footer-brand { color:#d4af37; font-weight:700; font-size:13px; }
  .qr-placeholder { width:60px; height:60px; background:#fff; border-radius:4px; display:flex; align-items:center; justify-content:center; font-size:9px; color:#999; text-align:center; }

  /* BADGE */
  .badge { display:inline-block; background:#d4af37; color:#1a3a5c; padding:3px 10px; border-radius:12px; font-size:11px; font-weight:700; margin-bottom:8px; }

  /* DIVIDER */
  .divider { height:1px; background:#e8e8e8; margin:0 32px; }
</style>
</head>
<body>
<div class="page">

  <!-- HEADER -->
  <div class="header">
    <div>
      <div class="header-logo">REALTY<span>PRO</span></div>
      <div style="font-size:11px;color:#aab8c8;margin-top:2px;">Asesoría Inmobiliaria Profesional</div>
    </div>
    <div class="header-tag">${(prop.operacion || 'EN VENTA').toUpperCase()}</div>
  </div>

  <!-- HERO -->
  <div class="hero">
    <div class="badge">${prop.tipo_propiedad || 'Propiedad'}</div>
    <div class="prop-title">${prop.titulo || 'Propiedad en Venta'}</div>
    <div class="prop-address">📍 ${[prop.colonia, prop.ciudad, prop.estado].filter(Boolean).join(', ') || prop.direccion || ''}</div>
    <div class="price-tag">${prop.precio || 'Precio a consultar'}</div>
    ${prop.precio_m2 ? `<div class="price-m2">${prop.precio_m2} por m²</div>` : ''}
  </div>

  <!-- PHOTOS -->
  <div class="photos-section">
    <div class="section-title">Fotografías</div>
    <div class="photos-grid">
      ${photoHTML}
    </div>
  </div>

  <div class="divider"></div>

  <!-- TWO COLUMN: SPECS + CARACTERÍSTICAS -->
  <div class="two-col">
    <div class="col-section">
      <div class="section-title" style="margin-bottom:10px;">Ficha técnica</div>
      <table>${specsHTML}</table>
    </div>
    <div class="col-section">
      ${charHTML ? `
      <div class="section-title" style="margin-bottom:10px;">Características</div>
      <ul>${charHTML}</ul>
      ` : ''}
      ${prop.descripcion_ubicacion ? `
      <div class="section-title" style="margin-top:16px;margin-bottom:10px;">Zona y ubicación</div>
      <p style="font-size:12px;color:#444;line-height:1.6;">${prop.descripcion_ubicacion}</p>
      ` : ''}
    </div>
  </div>

  <div class="divider"></div>

  <!-- DESCRIPTION -->
  ${prop.descripcion_larga ? `
  <div class="desc-section" style="padding-top:16px;">
    <div class="section-title">Descripción</div>
    <p class="desc-text">${prop.descripcion_larga}</p>
  </div>
  ` : ''}

  <!-- ADDRESS FULL -->
  ${prop.direccion ? `
  <div style="padding:8px 32px 16px;">
    <div class="section-title">Dirección</div>
    <p style="font-size:13px;color:#444;">${prop.direccion}</p>
  </div>
  ` : ''}

  <!-- FOOTER -->
  <div class="footer">
    <div>
      <div class="footer-brand">RealtyPRO Asesores</div>
      <div style="margin-top:4px;">Tel: +52 442 000 0000 · info@realtypro.mx</div>
      <div style="margin-top:2px;">Ficha generada el ${today} · Precio sujeto a cambio sin previo aviso</div>
    </div>
    <div class="qr-placeholder">Escanea<br/>para info</div>
  </div>

</div>
</body>
</html>`;

const buffer = Buffer.from(html, 'utf8');
const binaryHtml = await this.helpers.prepareBinaryData(buffer, 'index.html', 'text/html');

return [{ json: { html, chatId: session.chatId, prop, photoCount: photos.length }, binary: { htmlFile: binaryHtml } }];

